# Review package: ed3ba1c1348b0c5997d877628a0e863563bcb509..HEAD

## Commits
55b5fb8 fix: fold typographic apostrophe in topWords

## Files changed
 src/textstats.js      | 2 +-
 test/topWords.test.js | 4 ++++
 2 files changed, 5 insertions(+), 1 deletion(-)

## Diff
diff --git a/src/textstats.js b/src/textstats.js
index e1b3954..7b72f26 100644
--- a/src/textstats.js
+++ b/src/textstats.js
@@ -98,21 +98,21 @@ const STOP_WORDS = new Set([
  * @param {number} n How many entries to return; a non-negative integer.
  * @returns {Array<{word: string, count: number}>}
  */
 function topWords(text, n) {
   assertText('topWords', text);
   if (!Number.isInteger(n) || n < 0) {
     throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
   }
   const counts = new Map();
   for (const token of tokenize(text)) {
-    const word = token.toLowerCase().replace(/'/g, "'");
+    const word = token.toLowerCase().replace(/\u2019/g, "'");
     if (STOP_WORDS.has(word)) {
       continue;
     }
     counts.set(word, (counts.get(word) ?? 0) + 1);
   }
   return [...counts]
     .map(([word, count]) => ({ word, count }))
     .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
     .slice(0, n);
 }
diff --git a/test/topWords.test.js b/test/topWords.test.js
index 9dacd74..495f5b0 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -34,20 +34,24 @@ test('returns word and count pairs', () => {
 });

 test('orders words by count, highest first', () => {
   assert.deepEqual(topWords('pear apple apple fig fig fig', 3), [
     { word: 'fig', count: 3 },
     { word: 'apple', count: 2 },
     { word: 'pear', count: 1 },
   ]);
 });

+test('folds the typographic apostrophe into the straight one when counting', () => {
+  assert.deepEqual(topWords("keeper’s keeper’s", 5), [{ word: "keeper's", count: 2 }]);
+});
+
 test('throws a TypeError naming the function for a non-string', () => {
   for (const bad of [undefined, null, 3, {}, ['apple']]) {
     assert.throws(() => topWords(bad, 3), (err) => {
       assert.ok(err instanceof TypeError);
       assert.ok(err.message.startsWith('topWords:'));
       return true;
     });
   }
 });

